// AJUSTE AQUI: nomes EXATOS dos status na sua List do ClickUp.
const STATUS = {
  start: "em progresso",
  stop: "planejando",
  blocked: "pausado",
  done: "finalizado",
};
const TEAM_ID = "9011440385";
const MEMBER_ID = 158519491;

const ev = $("Webhook: evento da task").first().json.body;
const card = $input.first().json;

// Identifica se o card é um ticket do Zammad
const ticketField = (card.custom_fields || []).find((f) => f.name === "Ticket");
const hasTicketLink =
  !!ticketField &&
  ticketField.value != null &&
  String(ticketField.value).trim() !== "";
const isTicketName = /^Ticket#/i.test(card.name || "");
const isTicket = hasTicketLink || isTicketName;

const status = STATUS[ev.event];
if (!status) throw new Error("Evento desconhecido: " + ev.event);

const out = [];

// Salva as horas SOMENTE no 'done', para QUALQUER card (inclusive tickets do Zammad)
if (ev.event === "done") {
  for (const i of ev.intervals || []) {
    out.push({
      json: {
        method: "POST",
        url: `https://api.clickup.com/api/v2/team/${TEAM_ID}/time_entries`,
        body: {
          tid: String(ev.clickupId),
          start: Number(i.start),
          duration: Number(i.duration),
          description: `${ev.description} (TaskWarrior ${String(ev.uuid || "").slice(0, 8)})`,
          billable: false,
          assignee: MEMBER_ID,
        },
      },
    });
  }
}

// Annotations do TaskWarrior viram UM comentario no card, SOMENTE no 'done'
// (tambem em tickets do Zammad, como as horas)
if (ev.event === "done" && (ev.annotations || []).length > 0) {
  const fmt = (ms) =>
    new Date(Number(ms)).toLocaleDateString("pt-BR", {
      timeZone: "America/Fortaleza",
    });
  const linhas = ev.annotations.map((a) => `- [${fmt(a.entry)}] ${a.description}`);
  out.push({
    json: {
      method: "POST",
      url: `https://api.clickup.com/api/v2/task/${ev.clickupId}/comment`,
      body: {
        comment_text: "Anotações do TaskWarrior:\n" + linhas.join("\n"),
        notify_all: false,
      },
    },
  });
}

// Altera o status APENAS se o card NÃO for um ticket
if (!isTicket) {
  out.push({
    json: {
      method: "PUT",
      url: `https://api.clickup.com/api/v2/task/${ev.clickupId}`,
      body: { status },
    },
  });
}

return out;
